/**
 * The venue manifest: the single source of truth for both the 3D scene and the
 * VVIP table inventory.
 *
 * It is generated by scripts/build-venue.py straight out of the approved SketchUp
 * GLB, so the map and the sellable inventory are the same data by construction and
 * cannot drift apart. Nothing here is hand-typed; re-run the build to change it.
 *
 * Coordinates are metres, glTF Y-up, recentred so X=0 is the stage axis and Z=0 is
 * mid-field. Facing the stage is -Z. Low (negative) X is the audience's LEFT, which
 * is Platform A.
 */

export type Tier = 'starr-castle' | 'cold-rush'

export interface VenueTable {
  /**
   * A01-A30 / B01-B30: one per VVIP set, the blue coffee table in the crook of its L of
   * sofas. Numbered from the stage back; 01-15 is always Starr Castle.
   */
  id: string
  platform: 'A' | 'B'
  /** 1 = nearest the stage, 10 = furthest. Three tables per row. */
  row: number
  seat: number
  tier: Tier
  /** Tanzanian shillings. */
  price: number
  /** Centre of the coffee-table top. */
  pos: [number, number, number]
  /** Where to stand the camera to show this table's own view of the stage. */
  camera: { pos: [number, number, number]; target: [number, number, number] }
}

interface Boxish {
  centre: [number, number, number]
  size: [number, number, number]
}

export interface Venue {
  meta: { site: string; units: string; up: string; axis_x: number; note: string; origin_shift: number[] }
  ground: { size: [number, number]; centre: [number, number] }
  stage: {
    deck: Boxish
    catwalk: Boxish
    roof: Boxish
    screen: Boxish
    line_array: Boxish[]
  }
  platforms: Array<{ id: 'A' | 'B'; centre: [number, number, number]; size: [number, number, number]; backdrop: Boxish }>
  cocktail: { count: number; size: [number, number, number]; note: string; positions: [number, number, number][] }
  barriers: { count: number; positions: [number, number, number][] }
  towers: Boxish[]
  excluded: { crowd_figures: number; note: string }
  tables: VenueTable[]
}

export const TIER_LABEL: Record<Tier, string> = {
  'starr-castle': 'Starr Castle',
  'cold-rush': 'Cold Rush',
}

/** Brand-accurate tier colours, sampled from the campaign artwork in the GLB. */
export const TIER_COLOUR: Record<Tier, number> = {
  'starr-castle': 0x2a5cff,
  'cold-rush': 0x102060,
}

/**
 * Tier colours for the table picker, which is seen at night from the air: Starr Castle
 * glacier white, Cold Rush Jolt Blue lifted so it reads against the dark ground.
 * (TIER_COLOUR above is the artwork-accurate pair the walkthrough's markers use.)
 */
export const PICK_COLOUR: Record<Tier, number> = {
  'starr-castle': 0xcfeaff,
  'cold-rush': 0x2f62ff,
}

export const formatTzs = (n: number) => `${(n / 1_000_000).toFixed(0)}M TZS`
